Gold Result:
('Allison Hill',)
*/

-- Prediction Query
SELECT home_team_api_id AS team_api_id FROM Match WHERE season = '2015/2016' GROUP BY home_team_api_id HAVING SUM(CASE WHEN home_team_goal < away_team_goal THEN 1 ELSE 0 END) > 0 ORDER BY SUM(CASE WHEN home_team_goal < away_team_goal THEN 1 ELSE 0 END) ASC, team_api_id NULLS LAST LIMIT 1;

